# name: cell_unanimity
# description: Fraction of (set, target) cells with >=2 responses where all responses agree; observed above null means people are more consistent with each other (more deterministic/extreme yes-probabilities) than the model's graded posterior predicts, below null means more disagreement.
def test_statistic(df):
    g = df.groupby(["number_set", "target"])["rating"].agg(["mean", "size"])
    g = g[g["size"] >= 2]
    if len(g) == 0:
        return 0.0
    return float(((g["mean"] == 0) | (g["mean"] == 1)).mean())

# name: trial_index_drift
# description: Pearson correlation between trial_index and the yes response; the model has no session dynamics so predicts ~0 — observed above null means people say yes more as the session goes on, below null means they grow more conservative.
def test_statistic(df):
    x = df["trial_index"].astype(float).to_numpy()
    r = df["rating"].astype(float).to_numpy()
    if x.std() == 0 or r.std() == 0:
        return 0.0
    return float(np.corrcoef(x, r)[0, 1])
